    if (all(#HumiditySensor).humiditySensor_humidity >| 60) {
timeout = true
}
if (timeout == true) {
all(#Dehumidifier).dehumidifier_setDehumidifierMode("continuousDehumidifying")
}
all(#Switch).switch_off()

